const conc = [.1, .2, .3, .4, .5, .6, .7, .8, .9];
const c = OLI.randomArrayItem(conc) .toPrecision(3);

const kf = 1.9e16;
const kd = c/kf;
const sol = ((kd/4)**(1/3)) .toPrecision(3);

const conc_cu = ((kd/4)**(1/3)) .toPrecision(2);
const cu_low = 0.95*conc_cu;
const cu_high = 1.05*conc_cu;

const conc_cn = (2*conc_cu) .toPrecision(2);
const cn_low = 0.95*conc_cn;
const cn_high = 1.05*conc_cn;

const check = conc_cu*(conc_cn)**2;

// Expose variables to OLI
module.exports = {
  c, sol, conc_cu, conc_cn, check, cu_low, cu_high, cn_low, cn_high
};
